 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    points = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]

    # Full-width colored rows encode a repeating horizontal stripe sequence.
    if points and all(all(v == row[0] for v in row) for row in grid if row[0] != 0):
        row_marks = {r: grid[r][0] for r in range(h) if grid[r][0] != 0}
        for period in range(1, h + 1):
            residues = {}
            valid = True
            for r, color in row_marks.items():
                k = r % period
                if k in residues and residues[k] != color:
                    valid = False
                    break
                residues[k] = color
            if valid:
                break
        for k in range(period):
            if k not in residues:
                for step in range(1, period + 1):
                    prev = (k - step) % period
                    if prev in residues:
                        residues[k] = residues[prev]
                        break
        return [[residues[r % period] for _ in range(w)] for r in range(h)]

    # Otherwise the marks are parallel diagonal lines, periodic in c-r.
    for period in range(1, max(h, w) + 1):
        residues = {}
        valid = True
        for r, c, color in points:
            k = (c - r) % period
            if k in residues and residues[k] != color:
                valid = False
                break
            residues[k] = color
        if valid:
            break
    for k in range(period):
        if k not in residues:
            for step in range(1, period + 1):
                prev = (k - step) % period
                if prev in residues:
                    residues[k] = residues[prev]
                    break
    return [[residues[(c - r) % period] for c in range(w)] for r in range(h)]

